"""On-device semantic merchant classifier — training corpus, canonicalizer, and a
JS-replicable char n-gram featurizer + linear model.

This is a genuine text-classification model (multinomial logistic regression over
word-boundary character n-grams), trained on a RICH, MULTILINGUAL corpus of
category *definitions and diverse examples* — not a merchant dictionary. Sub-word
features let it generalize to previously unseen, abbreviated, and international
merchants (e.g. "farmacia"/"apotheke"/"pharmacie" -> Healthcare; "ristorante"/
"taqueria"/"brasserie" -> Dining) without ever having seen those exact names.

The featurizer here is intentionally simple and deterministic so the identical
inference can run IN THE BROWSER (see web/classifier.js) from exported weights —
tiny (~KB), instant cold-start, zero model download, zero network.
"""

import re

from reference import taxonomy

CATEGORIES = list(taxonomy.CATEGORY_NAMES)   # the 10 fixed categories

# ---- canonical merchant extraction ---------------------------------------
_PHONE = re.compile(r"\b(?:\+?\d[\d\-\.\(\) ]{6,}\d)\b")
_LONGNUM = re.compile(r"\b[a-z]*\d{3,}[a-z0-9]*\b")     # store/txn ids, card tails
_URL = re.compile(r"\b(?:https?://|www\.)\S+|\b[a-z0-9\-]+\.(?:com|net|org|io|co|es|de|fr|mx|uk)\b")
_NOISE = re.compile(r"\b(pos|debit|credit|card|purchase|payment|pmt|ach|ppd|des|id|ref|"
                    r"recurring|trans|transaction|auth|authorized|online|web|recur|bill|"
                    r"billpay|checkcard|ckcd|visa|mastercard|amex|xxxx|usd|eur|gbp|mxn|"
                    r"the|inc|llc|ltd|co|corp|sa|gmbh|srl|bv|of|and)\b")
_STATES = re.compile(r"\b(a[klrz]|c[aot]|d[ce]|fl|ga|hi|i[adln]|k[sy]|la|m[adeinost]|"
                     r"n[cdehjmvy]|o[hkr]|pa|ri|s[cd]|t[nx]|ut|v[at]|w[aivy])\b")
_MULTISPACE = re.compile(r"\s+")


def canonicalize(desc):
    """Strip bank-processing boilerplate, dates, phone numbers, transaction ids,
    card prefixes, URLs, and location codes — leaving the core merchant text.
    The ORIGINAL description is preserved by the caller."""
    s = (desc or "").lower()
    s = s.replace("*", " ").replace("#", " ").replace("/", " ")
    s = re.sub(r"https?://|www\.", " ", s)
    # keep a domain's NAME but drop the TLD (steamgames.com -> steamgames)
    s = re.sub(r"\b([a-z][a-z0-9\-]{2,})\.(?:com|net|org|io|co|es|de|fr|mx|uk|it|pt|eu)\b", r"\1", s)
    s = _PHONE.sub(" ", s)
    s = re.sub(r"\d{1,2}[\-/]\d{1,2}(?:[\-/]\d{2,4})?", " ", s)   # dates
    s = _LONGNUM.sub(" ", s)
    s = re.sub(r"[^a-zÀ-ſ ]+", " ", s)                  # keep letters (incl. accents)
    s = _NOISE.sub(" ", s)
    s = _STATES.sub(" ", s)
    s = _MULTISPACE.sub(" ", s).strip()
    return s


# ---- JS-replicable char n-gram featurizer --------------------------------
NGRAMS = (3, 4, 5)


def features(canonical):
    """Set of word-boundary char n-grams (sizes 3-5). Deterministic; mirrored 1:1
    in web/classifier.js so browser inference matches training exactly."""
    s = " " + _MULTISPACE.sub(" ", (canonical or "").strip()) + " "
    if s == "  ":
        return set()
    feats = set()
    L = len(s)
    for n in NGRAMS:
        if L >= n:
            for i in range(L - n + 1):
                g = s[i:i + n]
                if g != " " * n:
                    feats.add(g)
    return feats


