def build_training_examples():
    """Return (texts, labels) — one example per whitespace token phrase is too
    sparse, so we use short phrases: split each category blob into overlapping
    1-3 word phrases to give the model diverse, realistic merchant-length inputs."""
    texts, labels = [], []
    for cat, blob in CORPUS.items():
        toks = blob.split()
        # single tokens
        for t in toks:
            texts.append(t); labels.append(cat)
        # 2- and 3-word phrases (sliding) — teaches multi-word merchant patterns
        for k in (2, 3):
            for i in range(len(toks) - k + 1):
                texts.append(" ".join(toks[i:i + k])); labels.append(cat)
    # real-brand world knowledge — each brand (weighted a few times so it registers)
    for cat, blob in BRANDS.items():
        for t in blob.split():
            for _ in range(3):
                texts.append(t); labels.append(cat)
    return texts, labels
